function getSpeechRecognitionConstructor() {
  if (typeof window === 'undefined') {
    return null;
  }

  return (
    window.SpeechRecognition ||
    window.webkitSpeechRecognition ||
    null
  );
}

export function isSpeechRecognitionSupported() {
  return (
    typeof window !== 'undefined' &&
    ('SpeechRecognition' in window ||
      'webkitSpeechRecognition' in window)
  );
}

export function createRecognizer({
  lang = 'en-AU',
  interimResults = true,
  continuous = false,
} = {}) {
  if (!isSpeechRecognitionSupported()) {
    return null;
  }

  const SpeechRecognition =
    window.SpeechRecognition ||
    window.webkitSpeechRecognition;

  const recognizer = new SpeechRecognition();

  recognizer.lang = lang;
  recognizer.interimResults = interimResults;
  recognizer.continuous = continuous;
  recognizer.maxAlternatives = 1;

  return recognizer;
}

export function isSpeechSynthesisSupported() {
  return (
    typeof window !== 'undefined' &&
    'speechSynthesis' in window
  );
}

// --- Speech output --------------------------------------------------------

export const VOICE_PROFILE = {
  lang: 'en-AU',
  rate: 1.08,
  pitch: 1.0,
  volume: 1,
};

let currentUtterance = null;
const cachedVoiceByLang = new Map();
const voiceLoadPromiseByLang = new Map();

// Voices whose names are near-universally male across Chrome/Edge/Safari/
// Windows/macOS. These are EXCLUDED outright, even if nothing else in the
// pool scores higher — this is what closes the "sometimes a male voice
// slips through" gap, rather than just hoping a female hint outscores it.
const MALE_VOICE_BLOCKLIST = [
  'david', 'mark', 'james', 'george', 'daniel', 'alex', 'fred', 'aaron',
  'ryan', 'guy', 'matthew', 'tom', 'oliver', 'william', 'will', 'thomas',
  'male', 'man', 'google uk english male', 'google 中文 male',
];

// Tiered scoring for the remaining (non-blocklisted) pool — best-sounding
// neural/natural voices win first, named premium voices next, generic
// female-hinted names last.
const VOICE_TIERS = [
  { score: 3, patterns: ['neural', 'natural', 'online (natural)', 'premium'] },
  {
    score: 2,
    patterns: [
      'aria', 'jenny', 'sonia', 'emma', 'ava', 'michelle',
      'samantha', 'moira', 'tessa', 'karen',
      'google uk english female', 'google us english',
    ],
  },
  { score: 1, patterns: ['female', 'woman', 'zira', 'victoria', 'susan', 'linda', 'eva'] },
];

function isMaleVoiceName(name) {
  const lower = name.toLowerCase();
  return MALE_VOICE_BLOCKLIST.some((hint) => lower.includes(hint));
}

function scoreVoiceName(name) {
  const lower = name.toLowerCase();
  for (const tier of VOICE_TIERS) {
    if (tier.patterns.some((p) => lower.includes(p))) return tier.score;
  }
  return 0;
}

function pickFemaleVoice(voices, lang) {
  if (!voices || voices.length === 0) return null;

  const langPrefix = lang.split('-')[0].toLowerCase();
  const exactLocale = voices.filter((v) => v.lang?.toLowerCase() === lang.toLowerCase());
  const sameLanguage = voices.filter((v) => v.lang?.toLowerCase().startsWith(langPrefix));
  const pool = exactLocale.length ? exactLocale : sameLanguage.length ? sameLanguage : voices;

  // Hard-exclude known-male voices from the candidate pool first.
  const nonMale = pool.filter((v) => !isMaleVoiceName(v.name));
  const candidates = nonMale.length ? nonMale : pool; // don't end up with nothing at all

  const ranked = candidates
    .map((voice) => ({ voice, score: scoreVoiceName(voice.name) }))
    .sort((a, b) => b.score - a.score);

  return ranked[0]?.voice || candidates[0] || null;
}

// Polls for a short window instead of a single 500ms fallback — some
// browsers populate the voice list in more than one 'voiceschanged' burst,
// so a single early read can catch a still-partial list.
function loadVoices() {
  return new Promise((resolve) => {
    const existing = window.speechSynthesis.getVoices();
    if (existing.length > 0) {
      resolve(existing);
      return;
    }

    let settled = false;
    const finish = (voices) => {
      if (settled) return;
      settled = true;
      resolve(voices);
    };

    window.speechSynthesis.onvoiceschanged = () => {
      finish(window.speechSynthesis.getVoices());
    };

    let attempts = 0;
    const poll = setInterval(() => {
      attempts += 1;
      const voices = window.speechSynthesis.getVoices();
      if (voices.length > 0 || attempts >= 6) {
        clearInterval(poll);
        finish(voices);
      }
    }, 200);
  });
}

async function resolveVoice(lang) {
  if (cachedVoiceByLang.has(lang)) return cachedVoiceByLang.get(lang);

  if (!voiceLoadPromiseByLang.has(lang)) {
    voiceLoadPromiseByLang.set(
      lang,
      loadVoices().then((voices) => {
        const voice = pickFemaleVoice(voices, lang);
        cachedVoiceByLang.set(lang, voice);
        return voice;
      })
    );
  }

  return voiceLoadPromiseByLang.get(lang);
}

// Call this early (e.g. when voice mode is turned on, or on mount) so the
// voice list is warm well before the first speak() call — avoids any
// window where an utterance could go out on the browser's raw default.
export function primeVoices(lang = VOICE_PROFILE.lang) {
  if (!isSpeechSynthesisSupported()) return;
  resolveVoice(lang);
}

export async function getPreferredVoice(lang = VOICE_PROFILE.lang) {
  return resolveVoice(lang);
}

// Now async: always waits for a resolved voice before the utterance is
// dispatched, so every single utterance — including the very first one —
// uses the correct female voice. No more "goes out on browser default"
// window.
export async function speak(
  text,
  {
    lang = VOICE_PROFILE.lang,
    rate = VOICE_PROFILE.rate,
    pitch = VOICE_PROFILE.pitch,
    volume = VOICE_PROFILE.volume,
    onStart,
    onEnd,
    onError,
  } = {}
) {
  if (!isSpeechSynthesisSupported() || !text) {
    onError?.('unsupported');
    return null;
  }

  const voice = await resolveVoice(lang);

  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = lang;
  utterance.rate = rate;
  utterance.pitch = pitch;
  utterance.volume = volume;
  if (voice) utterance.voice = voice;

  utterance.onstart = () => onStart?.();

  utterance.onend = () => {
    if (currentUtterance === utterance) currentUtterance = null;
    onEnd?.();
  };

  utterance.onerror = (event) => {
    if (currentUtterance === utterance) currentUtterance = null;
    if (event.error === 'interrupted' || event.error === 'canceled') {
      onEnd?.();
      return;
    }
    onError?.(event.error);
  };

  currentUtterance = utterance;
  window.speechSynthesis.speak(utterance);

  return utterance;
}

export function cancelSpeech() {
  if (!isSpeechSynthesisSupported()) return;
  window.speechSynthesis.cancel();
  currentUtterance = null;
}

export default {
  isSpeechRecognitionSupported,
  createRecognizer,
  isSpeechSynthesisSupported,
  speak,
  cancelSpeech,
  getPreferredVoice,
  primeVoices,
  VOICE_PROFILE,
};
